import React, { useState } from "react";
import "./BudgetLimits.css";

function BudgetLimits({ formData = {}, onSave }) {
  const priorities = formData.spendingPriorities || {};

  // ✅ safe filter
  const activeCategories = Object.entries(priorities)
    .filter(([_, value]) => Number(value) >= 3)
    .map(([key]) => key);

  const [limits, setLimits] = useState({});

  const handleChange = (category, value) => {
    setLimits(prev => ({
      ...prev,
      [category]: value
    }));
  };

  const handleSubmit = async () => {
    const finalData = {
      ...formData,
      budgetLimits: limits
    };

    try {
      const res = await fetch("http://localhost:5000/save-budget", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(finalData)
      });

      if (res.ok) alert("Saved successfully!");
      else alert("Failed to save data");

      if (onSave) onSave(finalData);
    } catch {
      alert("Server connection failed");
    }
  };

  return (
    <div className="budget-container">
      <div className="budget-card">
        <h2 className="budget-title">Set Monthly Budget Limits</h2>

        {activeCategories.length === 0 ? (
          <p style={{ textAlign: "center", color: "grey" }}>
            No categories selected for budgeting
          </p>
        ) : (
          activeCategories.map((cat) => (
            <div key={cat} className="form-group">
              <label className="form-label">{cat}</label>
              <input
                type="number"
                className="form-input"
                placeholder="Enter amount"
                value={limits[cat] || ""}
                onChange={(e) => handleChange(cat, e.target.value)}
              />
            </div>
          ))
        )}

        <button className="next-button" onClick={handleSubmit}>
          Save Budget
        </button>
      </div>
    </div>
  );
}

export default BudgetLimits;
